export const PLATFORM=['LinkedIn','X','Instagram','Threads','TikTok','Facebook','YouTube'];
export const PROJECTS=[{id:'sod',name:'SØD Ecosystem Global',priority:100,type:'PRIMARY'},{id:'orbita',name:'Órbita',priority:50,type:'SECONDARY'},{id:'kadmontech',name:'Kadmontech',priority:40,type:'SECONDARY'}];
export const PILLARS=['Construcción diaria de SØD','IA aplicada','Founder journey','Personas, eventos y conexiones','Proyectos y experimentos','Ideas y criterio'].map((name,i)=>({id:`p${i+1}`,name,priority:100-i*10}));
export const TABLES=['sources','stories','ideas','mother_pieces','content_items','content_variants','calendar_slots','learnings'];
export const uid=()=>globalThis.crypto.randomUUID();
const clone=value=>structuredClone(value);
const baseState=()=>({version:1,profile:{id:'ivan',name:'Iván Cristini',slug:'ivan-cristini',positioning:'Fundador que construye SØD diariamente y trabaja con IA aplicada, sistemas, proyectos y conexiones estratégicas.',voice:'Directo, humano, basado en evidencia',social_accounts:PLATFORM.map((platform,i)=>({platform,handle:['@ivancristini','@IvanCristini','@ivancristini14','@ivancristini14','@ivan.cristini','Iván Cristini','@ivancristini3949'][i],url:['https://www.linkedin.com/in/ivancristini/','https://x.com/IvanCristini','https://www.instagram.com/ivancristini14/','https://www.threads.com/@ivancristini14','https://www.tiktok.com/@ivan.cristini','https://www.facebook.com/profile.php?id=61566999627436','https://www.youtube.com/@ivancristini3949'][i]}))},settings:{experiences:null},...Object.fromEntries(TABLES.map(t=>[t,[]]))});
export const storyDebt=s=>s.all('stories').filter(story=>story.status==='READY'&&!s.all('ideas').some(idea=>idea.story_id===story.id&&s.all('content_items').some(content=>content.idea_id===idea.id||s.all('mother_pieces').some(mother=>mother.id===content.mother_piece_id&&mother.idea_id===idea.id))));
export function deriveStats(s){const sources=s.all('sources');const since=Date.now()-7*864e5;const weekly=sources.filter(x=>new Date(x.captured_at||x.created_at).getTime()>=since&&x.status!=='ARCHIVED');const expected=Number(s.settings.experiences);return {captures:weekly.length,captureRate:expected>0?Math.min(100,Math.round(weekly.length/expected*100)):null,storyDebt:storyDebt(s).length,stories:s.all('stories').filter(x=>!['USED','ARCHIVED'].includes(x.status)).length,ideas:s.all('ideas').filter(x=>!['USED','ARCHIVED'].includes(x.status)).length,ready:s.all('content_variants').filter(x=>x.status==='READY').length,approved:s.all('content_variants').filter(x=>x.status==='APPROVED').length,scheduled:s.all('calendar_slots').length};}
export class ContentStore{
 constructor(adapter){this.adapter=adapter;this.state=baseState();this.listeners=new Set();this.urls=new Map();this.queue=Promise.resolve();}
 get profile(){return this.state.profile;}
 get settings(){return this.state.settings;}
 all(table){if(!TABLES.includes(table))throw Error('Tabla inválida');return clone(this.state[table]);}
 async init(){const saved=await this.adapter.load();if(saved){this.validateState(saved);this.state=saved;}for(const row of this.state.sources){if(row.attachment_id){const blob=await this.adapter.getFile(row.attachment_id);if(blob)row.file_url=this.makeUrl(row.attachment_id,blob);}}return this;}
 subscribe(fn){this.listeners.add(fn);return()=>this.listeners.delete(fn);}
 transact(fn){const run=this.queue.then(async()=>{const next=clone(this.state);const result=fn(next);this.validateState(next);await this.adapter.save(next);this.state=next;for(const cb of this.listeners){try{cb();}catch(e){console.error(e);}}return clone(result);});this.queue=run.catch(()=>{});return run;}
 async add(table,data){if(!TABLES.includes(table)||table==='calendar_slots')throw Error('Usá Programar para crear un slot');return this.transact(state=>{const row={...data,id:uid(),profile_id:'ivan',created_at:new Date().toISOString()};if(!row.status)row.status=({sources:'CAPTURED',stories:'READY',ideas:'IDEA',mother_pieces:'DRAFT',content_items:'DRAFT',content_variants:'DRAFT',learnings:'DRAFT'})[table];if(table==='sources'){row.context_status=row.context_status||row.status;row.captured_at=row.captured_at||row.created_at;row.privacy=row.privacy||'PRIVATE';}state[table].push(row);return row;});}
 async update(table,id,patch){return this.transact(state=>{if(!TABLES.includes(table)||table==='calendar_slots')throw Error('Tabla inválida');const row=state[table].find(x=>x.id===id);if(!row)throw Error('No encontramos el registro');const safe={...patch};delete safe.id;delete safe.profile_id;delete safe.created_at;if(table==='content_variants'){if(safe.status==='SCHEDULED')throw Error('Usá Programar para aprobar y asignar fecha');if(['copy','hook','media_url','cta','format','platform'].some(k=>k in safe&&safe[k]!==row[k])){safe.status='DRAFT';safe.scheduled_at=null;state.calendar_slots=state.calendar_slots.filter(x=>x.content_variant_id!==id);}if(safe.status&&safe.status!=='SCHEDULED'){safe.scheduled_at=null;state.calendar_slots=state.calendar_slots.filter(x=>x.content_variant_id!==id);}}Object.assign(row,safe);return row;});}
 async delete(table,id){return this.transact(state=>{if(!TABLES.includes(table))throw Error('Tabla inválida');const refs={sources:[['stories','source_id'],['mother_pieces','source_id']],stories:[['ideas','story_id']],ideas:[['content_items','idea_id'],['mother_pieces','idea_id']],mother_pieces:[['content_items','mother_piece_id']],content_items:[['content_variants','content_item_id']]};for(const [t,k]of refs[table]||[])if(state[t].some(x=>x[k]===id))throw Error('El registro tiene derivados. Archiválo para conservar su trazabilidad.');if(table==='content_variants')state.calendar_slots=state.calendar_slots.filter(x=>x.content_variant_id!==id);state[table]=state[table].filter(x=>x.id!==id);return true;});}
 async schedule(id,when){return this.transact(state=>{const variant=state.content_variants.find(x=>x.id===id);if(!variant)throw Error('Variante inexistente');if(!['APPROVED','SCHEDULED'].includes(variant.status))throw Error('Aprobá la variante antes de programarla');const time=new Date(when);if(!Number.isFinite(time.getTime())||time.getTime()<=Date.now())throw Error('Elegí una fecha y hora futura');variant.status='SCHEDULED';variant.scheduled_at=time.toISOString();let slot=state.calendar_slots.find(x=>x.content_variant_id===id);if(!slot){slot={id:uid(),profile_id:'ivan',content_variant_id:id};state.calendar_slots.push(slot);}Object.assign(slot,{platform:variant.platform,scheduled_at:variant.scheduled_at,status:'SCHEDULED'});return slot;});}
 async setSettings(patch){return this.transact(state=>{if('experiences'in patch&&patch.experiences!==null&&(!Number.isFinite(Number(patch.experiences))||Number(patch.experiences)<0))throw Error('Ingresá una cantidad válida');Object.assign(state.settings,patch);return state.settings;});}
 makeUrl(id,blob){if(this.urls.has(id))URL.revokeObjectURL(this.urls.get(id));const url=URL.createObjectURL(blob);this.urls.set(id,url);return url;}
 async attach(file){if(!file||file.size===0)throw Error('El archivo está vacío');if(file.size>50*1024*1024)throw Error('El límite local es de 50 MB por archivo');const id=uid();await this.adapter.putFile(id,file);return {attachment_id:id,file_url:this.makeUrl(id,file),file_name:file.name,file_type:file.type};}
 async fileUrl(id){if(this.urls.has(id))return this.urls.get(id);const blob=await this.adapter.getFile(id);return blob?this.makeUrl(id,blob):null;}
 async export(){await this.queue;const out=clone(this.state);out.exported_at=new Date().toISOString();out.export_note='Respaldo de texto y metadatos. Los archivos adjuntos permanecen en el navegador de origen.';for(const source of out.sources)if(source.attachment_id)source.file_url='';return JSON.stringify(out,null,2);}
 async import(json){let data;try{data=JSON.parse(json);}catch{throw Error('El archivo no contiene JSON válido');}this.validateState(data);return this.transact(state=>{for(const key of Object.keys(state))if(key in data)state[key]=clone(data[key]);for(const source of state.sources)if(source.attachment_id){source.file_url='';source.context_status='NEEDS_CONTEXT';source.status='NEEDS_CONTEXT';}return true;});}
 validateState(state){if(!state||typeof state!=='object'||state.version!==1||!state.profile||state.profile.id!=='ivan'||typeof state.profile.name!=='string'||!state.settings||Array.isArray(state.settings))throw Error('Formato de espacio incompatible');if(!Array.isArray(state.profile.social_accounts)||state.profile.social_accounts.some(account=>!account||!PLATFORM.includes(account.platform)||typeof account.handle!=='string'||typeof account.url!=='string'||!/^https?:\/\//i.test(account.url)))throw Error('Perfil social inválido');if(state.settings.experiences!==null&&state.settings.experiences!==undefined&&(!Number.isFinite(Number(state.settings.experiences))||Number(state.settings.experiences)<0))throw Error('Cantidad de experiencias inválida');const statuses={sources:['CAPTURED','NEEDS_CONTEXT','READY','ARCHIVED'],stories:['CAPTURED','DEVELOPING','READY','USED','ARCHIVED'],ideas:['IDEA','DEVELOPING','READY','USED','ARCHIVED'],mother_pieces:['DRAFT','READY','USED','ARCHIVED'],content_items:['DRAFT','READY','APPROVED','SCHEDULED','PUBLISHED','MEASURED','REUSABLE','ARCHIVED'],content_variants:['DRAFT','READY','APPROVED','SCHEDULED','PUBLISHED','MEASURED','REUSABLE','ARCHIVED'],calendar_slots:['SCHEDULED'],learnings:['DRAFT','READY','ARCHIVED']};const ids=new Set();for(const table of TABLES){if(!Array.isArray(state[table]))throw Error(`Falta tabla ${table}`);for(const row of state[table]){if(!row||typeof row!=='object'||typeof row.id!=='string'||!row.id||ids.has(row.id))throw Error('Identificadores inválidos');ids.add(row.id);if(row.profile_id!=='ivan')throw Error('El registro no pertenece al perfil local');if(!statuses[table].includes(row.status))throw Error(`Estado inválido: ${table}`);if(table!=='calendar_slots'&&typeof row.title!=='string'&&!['content_variants','learnings'].includes(table))throw Error('El título es obligatorio');if('title'in row&&(typeof row.title!=='string'||!row.title.trim()||row.title.length>300))throw Error('El título debe tener entre 1 y 300 caracteres');if(row.project_id&&!PROJECTS.some(x=>x.id===row.project_id))throw Error('Proyecto inválido');if(row.pillar_id&&!PILLARS.some(x=>x.id===row.pillar_id))throw Error('Pilar inválido');for(const field of ['file_url','media_url','published_url'])if(row[field]&&(typeof row[field]!=='string'||!/^(https?:\/\/|blob:)/i.test(row[field])))throw Error('URL inválida: usá https://');if(table==='sources'&&row.type==='URL'&&!row.file_url&&!row.text_content)throw Error('Agregá una URL');}}
 for(const table of TABLES)for(const row of state[table]){for(const field of ["summary","text_content","context","evidence","core_thesis","angle","objective","copy","hook","format","cta","file_name","type","story_type","finding","captured_at","event_date","scheduled_at","created_at"])if(row[field]!=null&&typeof row[field]!=="string")throw Error("Campo de texto inválido: "+field);for(const field of ["captured_at","event_date","scheduled_at","created_at"])if(row[field]&&!Number.isFinite(new Date(row[field]).getTime()))throw Error("Fecha inválida: "+field);}
 const links=[['stories','source_id','sources'],['ideas','story_id','stories'],['mother_pieces','source_id','sources'],['mother_pieces','idea_id','ideas'],['content_items','idea_id','ideas'],['content_items','mother_piece_id','mother_pieces'],['content_variants','content_item_id','content_items'],['calendar_slots','content_variant_id','content_variants']];for(const[table,key,parent]of links)for(const row of state[table])if(row[key]&&!state[parent].some(x=>x.id===row[key]))throw Error(`Relación inválida: ${table}`);
 for(const story of state.stories){const source=state.sources.find(x=>x.id===story.source_id);if(source?.project_id&&story.project_id!==source.project_id)throw Error('La historia debe conservar el proyecto de su fuente');}
 for(const v of state.content_variants){if(!v.content_item_id)throw Error('La variante necesita una pieza');if(!PLATFORM.includes(v.platform))throw Error('Plataforma inválida');if(['READY','APPROVED','SCHEDULED'].includes(v.status)&&!String(v.copy||'').trim())throw Error('Completá el texto antes de aprobar');}
 const scheduledIds=new Set();for(const slot of state.calendar_slots){if(scheduledIds.has(slot.content_variant_id))throw Error('Variante programada duplicada');scheduledIds.add(slot.content_variant_id);const v=state.content_variants.find(x=>x.id===slot.content_variant_id);if(v.status!=='SCHEDULED'||slot.scheduled_at!==v.scheduled_at||slot.platform!==v.platform||!Number.isFinite(new Date(slot.scheduled_at).getTime()))throw Error('Calendario inconsistente');}
 for(const v of state.content_variants)if(v.status==='SCHEDULED'&&!scheduledIds.has(v.id))throw Error('La variante programada necesita un slot');
 }
}
export class IndexedAdapter{
 async open(){if(this.db)return this.db;this.db=await new Promise((resolve,reject)=>{const r=indexedDB.open('content-os-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('workspace');r.result.createObjectStore('files');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('No se pudo abrir almacenamiento local. Revisá los permisos del navegador.'));});return this.db;}
 async request(store,mode,action){const db=await this.open();return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode);const req=action(tx.objectStore(store));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(Error('No se pudo guardar. Revisá el espacio disponible y exportá un respaldo.'));tx.onabort=()=>reject(Error('Guardado cancelado. Reintentá.'));});}
 load(){return this.request('workspace','readonly',s=>s.get('main'));}
 save(state){return this.request('workspace','readwrite',s=>s.put(state,'main'));}
 putFile(id,file){return this.request('files','readwrite',s=>s.put(file,id));}
 getFile(id){return this.request('files','readonly',s=>s.get(id));}
}
export const store=new ContentStore(new IndexedAdapter());
